entries[186414] = { ["name"] = "Rae'shalare, Flüstern des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDistanz Bogen\n95 - 129 Schaden Geschwindigkeit 3.00\n(37.3 Schaden pro Sekunde)\n+50 Beweglichkeit\n+75 Ausdauer\nErhöht Eure kritische Trefferwertung um + 54.\nErhöht Eure Tempowertung um + 45.\nHaltbarkeit 145 / 145\nKlassen: Jäger\nAnlegen: Gewährt die Fähigkeit, 'Klagender Pfeil' einzusetzen, was Eurem Ziel sowie anderen Gegnern in der Nähe Schattenschaden zufügt und getroffene Kreaturen zum Schweigen bringt.\nVerkaufspreis:" }
