entries[186421] = { ["name"] = "Verbotener nekromantischer Foliant", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, Euren kritischen Trefferwert für 15 Sek. um 48 zu erhöhen. Bis zu 3-mal stapelbar.\nBenutzen: Belebt die Überreste eines gefallenen Verbündeten für 30 Sek. als Skelettkrieger wieder. (10 Min Abklingzeit)\nVerkaufspreis:" }
entries[186422] = { ["name"] = "Foliant der monströsen Konstruktionen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nBenutzen: Studiert den Folianten und findet so die Schwäche des anvisierten Gegners heraus. Eure Schaden verursachenden Fähigkeiten haben eine sehr hohe Chance, Eurem studierten Gegner zusätzlich 229 Schattenschaden zuzufügen.\n\nBeim Studieren eines neuen Gegners gehen die Vorteile früherer Studien verloren. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[186423] = { ["name"] = "Titanische Okulardrüse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Solange Eure Gesundheit über 50% liegt, werdet Ihr als 'Würdig' erachtet, was Euren höchsten Sekundärwert um 73 erhöht. Wenn Eure Gesundheit unter 50% liegt, werdet Ihr als 'Unwürdig' erachtet, was Euren höchsten Sekundärwert um 73 verringert.\n\"Ein Preis, der vor langer Zeit für Wissen und Macht gezahlt wurde.\"\nVerkaufspreis:" }
entries[186424] = { ["name"] = "Splitter von Annhyldes Aegis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nBenutzen: Schützt Euch mit Annhyldes Aegis, die 8 Sek. lang den Schaden, den Ihr durch Gegner vor Euch erleidet, um 2015 verringert.\n\nWenn die Aegis mindestens 7052 Schaden absorbiert, wird sie überladen und stößt bei ihrem Ablauf gebündelte Macht aus, die allen Gegnern vor Euch 1123 Heiligschaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[186425] = { ["name"] = "Hingekritzeltes Wort des Rückrufs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nBenutzen: Verringert die verbleibende Abklingzeit Eures passenden Heilzaubers um 4 Sek.\n\nGilt nur für Heilerspezialisierungen. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[186427] = { ["name"] = "Flüsternder Splitter der Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Stärke\nAnlegen: Eine Stimme flüstert Euch zu und zwingt Euch regelmäßig, ihren Anordnungen Folge zu leisten. Wenn Ihr dies tut, werdet Ihr für 20 Sek. mit einer Erhöhung Eures höchsten Sekundärwerts um 210 belohnt.\nVerkaufspreis:" }
entries[186428] = { ["name"] = "Schattenkugel der Qual", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nBenutzen: Blickt in die Kugel, was Eure Meisterschaft für bis zu 40 Sek. um 301 erhöht, Euch aber im Verlauf von 2 Sek. ( 1263 * 4) Schattenschaden zufügt. Je länger Ihr hineinblickt, desto mehr werdet Ihr gequält und desto mehr Einsicht erhaltet Ihr. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[186429] = { ["name"] = "Karaffe des endlosen Heulens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 63.\nAnlegen: Eure kritischen Treffer haben eine Chance, Eure Stärke oder Beweglichkeit für 15 Sek. um 162 zu erhöhen. Falls Ihr dabei weniger als 50% Gesundheit habt, werdet Ihr zusätzlich im Verlauf von 6 Sek. um ( 525 * 4) Gesundheit geheilt.\nVerkaufspreis:" }
entries[186430] = { ["name"] = "Streckbankfragment der Pein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nAnlegen: Eure Schaden verursachenden Zauber und Fähigkeiten haben eine Chance, im Verlauf von 15 Sek. [Quellwert] zusätzlichen Schattenschaden zu verursachen.\n\nWenn ein Ziel stirbt, während es vom Streckbankfragment des Peinigers betroffen ist, hinterlässt es eine zerfetzte Seele, die Ihr einsammeln könnt, um Euren kritischen Trefferwert für 20 Sek. um 19 zu erhöhen.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[186431] = { ["name"] = "Schwarzseelenzwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nBenutzen: Verflucht einen Gegner und fügt ihm 12 Sek. lang alle 2 Sek. 307 Schattenschaden zu. Die Dauer erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 100%. (1 Min. 30 Sek. Abklingzeit) (1 Min, 30 Sek. Abklingzeit)\nAnlegen: Wenn ein Ziel stirbt, während es von der Schwarzseelenzwinge betroffen ist, hinterlässt es eine zerfetzte Seele, die Ihr einsammeln könnt, um Euren kritischen Trefferwert für 20 Sek. um 19 zu erhöhen.\nVerkaufspreis:" }
entries[186432] = { ["name"] = "Geborgener Fusionsverstärker", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nBenutzen: Ermächtigt Eure Waffen für 20 Sek., sodass Eure Angriffe eine sehr hohe Chance haben, 507 Arkanschaden zu verursachen. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[186433] = { ["name"] = "Reaktive Verteidigungsmatrix", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nAnlegen: Beim Erleiden von Schaden besteht eine Chance, dass Eure reaktive Verteidigungsmatrix ausgelöst wird und die nächsten 2293 erlittenen Schaden auf den Angreifer zurückwirft.\n\nDie reaktive Verteidigungsmatrix wird automatisch ausgelöst, wenn Eure Gesundheit unter 20% fällt. Dieser Effekt kann nur einmal alle 30 Sek. ausgelöst werden.\nVerkaufspreis:" }
entries[186434] = { ["name"] = "Gespinst aus verzerrten Schicksalen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Ihr getötet werdet und dabei maximal 16413 Schaden über den Tod hinaus erleidet, spult das Gespinst aus verzerrten Schicksalen Euer Schicksal zurück, ruft Euch so ins Leben zurück und heilt Euch um [ 16549 * (1 + Vielseitigkeit)] Gesundheit.\n\nDieser Effekt kann einmal alle 8 Min. auftreten.\nVerkaufspreis:" }
entries[186435] = { ["name"] = "Geschnitztes Elfenbeinandenken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+42 Intelligenz\nAnlegen: Ihr habt eine Chance, von Euren Verbündeten erlittenen Schaden vorherzusehen und sie sofort um 499 Gesundheit zu heilen, wenn sie verletzt werden.\nVerkaufspreis:" }
entries[186436] = { ["name"] = "Resonierende Silberglocke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Intelligenz\nAnlegen: Wenn Ihr einen Verbündeten mit weniger als 50% Gesundheit heilt, erfüllt eine spektrale Katze ihn mit zusätzlich 2839 Gesundheit. Die Katze rekonstituiert sich nach 30 Sek.\nVerkaufspreis:" }
entries[186437] = { ["name"] = "Relikt der Eisigen Weiten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Beweglichkeit\nAnlegen: Eure Angriffe haben eine hohe Chance, 73 Frostschaden zu verursachen und den Gegner mit 'Gefrorenes Herz' zu belegen.\nBenutzen: Ruft einen Neruber, der einen Gegner aus dem Hinterhalt angreift, ihn aufspießt und ihm 2726 körperlichen Schaden zufügt. Gegner in der Bahn des Nerubers, die mit Eurem Effekt 'Gefrorenes Herz' belegt sind, erleiden 229 Frostschaden. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[186438] = { ["name"] = "Seele eines alten Kriegers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+47 Stärke\nAnlegen: Im Kampf schwillt Eure Wut an, was Euer Tempo alle 20 Sek. um 25 erhöht. Bis zu 5-mal stapelbar.\nAnlegen: Wenn die Gesundheit eines Verbündeten in der Nähe unter 50% fällt, opfert Ihr 1177 Gesundheit, um ihn um diesen Wert zu heilen. Kann nur einmal pro Minute auftreten.\nVerkaufspreis:" }
entries[186439] = { ["name"] = "Köcher der Dunklen Waldläuferin", ["text"] = "Wird beim Aufheben gebunden\nRücken\n30 Rüstung\n+28 Beweglichkeit\n+42 Ausdauer\nErhöht Eure kritische Trefferwertung um + 37.\nErhöht Eure Tempowertung um + 19.\nKlassen: Jäger\nAnlegen: Alle 10 Schüsse wird 'Vernichtendes Feuer' ausgelöst, was bis zu 5 Gegner vor Euch trifft und ihnen 156 Schattenschaden zufügt.\nVerkaufspreis:" }
