entries[186469] = { ["name"] = "Verdammnisfalke der Illidari", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen Verdammnisfalken der Illidari oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einmal im Jahr entsteht ein Riss in der Zeit und es geschehen seltsame Dinge. Die Späher der Illidari und der Verdammniswandler waren ziemlich überrascht, sich in Tanaris wiederzufinden.\"\nBeute von:\nVerdammniswandler\nZone:\nTanaris" }
