entries[186476] = { ["name"] = "Grabschwinge von Sündensturz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Da die Anima in Sündensturz wieder fließt, konnte die Steinhauerin diese Steingeborenen damit anreichern, was sie zu wertvollen Verbündeten in den kommenden Schlachten macht.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[186477] = { ["name"] = "Bleiche Grabschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert einen ehrfürchtigen Ruf beim Vorstoß des Todes und den Abschluss des Angriffsmetaerfolges \"In der Offensive\".\n\n\"Grabschwingen kennen keine Furcht und sind nahezu unverwundbar, was für einen Angriff auf den Schlund perfekt ist.\"\nPakt:\nVenthyr\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive" }
entries[186478] = { ["name"] = "Obsidiangrabschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 70\n\n\"Am verdunkelten Himmel von Revendreth sieht man diese Kreaturen nicht kommen, bis es zu spät ist.\"\nPakt:\nVenthyr\nVerkäufer:\nChachi der Künstler\nZone:\nRevendreth\nKosten:\n7500" }
entries[186479] = { ["name"] = "Meisterhafte Grabschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Dieser meisterhaft gefertigte Steingeborene wurde von der Steinhauerin persönlich in Handarbeit hergestellt und wird nur jenen anvertraut, die sie als würdig erachtet.\"\nPakt:\nVenthyr\nBeute von:\nStygischer Steinzermalmer\nZone:\nKorthia" }
entries[186480] = { ["name"] = "Kampferprobter Aquilon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert einen ehrfürchtigen Ruf beim Vorstoß des Todes und den Abschluss des Angriffsmetaerfolges \"In der Offensive\".\n\n\"Der Aquilon kann ein wertvoller Verbündeter im Kampf sein. Seine Fähigkeiten übertreffen jene des Phalynx.\"\nPakt:\nKyrianer\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nKosten:\n1000\nErfolg:\nIn der Offensive" }
