entries[186483] = { ["name"] = "Aquilon der Verschmähten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese mächtigen Zenturionen wurden von den Verschmähten ursprünglich mithilfe gestohlener Baupläne erschaffen, doch heute machen sie sich in den gesamten Schattenlanden einen Namen.\"\nPakt:\nKyrianer\nBeute von:\nWilder Weltenknacker\nZone:\nKorthia" }
entries[186484] = { ["name"] = "Leerengeschmiedete Schienbeinschützer", ["text"] = "Wird beim Aufheben gebunden\nFüße Platte\n9 Rüstung\n+3 [Stärke oder Intelligenz]\n+4 Ausdauer\nErhöht Eure kritische Trefferwertung um + 4.\nErhöht Eure Tempowertung um + 2.\nHaltbarkeit 80 / 80\nVerkaufspreis:" }
entries[186485] = { ["name"] = "Aquilon des Aszendenten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 70\n\n\"Der Aquilon kann blitzschnell Aspiranten, Provosten und sogar Aufgestiegene von Ort zu Ort transportieren. Hey, manchmal werden einem eben die Flügel müde.\"\nPakt:\nKyrianer\nVerkäufer:\nAdjutant Galos\nZone:\nBastion\nKosten:\n7500" }
