entries[186487] = { ["name"] = "Harnisch der maldraxxischen Leichenfliege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Leichenfliegen waren einst in ganz Maldraxxus zu finden, aber viele starben aufgrund des Mangels an Anima. Da die Anima wieder fließt, schwärmen sie jetzt aus.\"\nPakt:\nNekrolords\nZone:\nMaldraxxus" }
entries[186488] = { ["name"] = "Harnisch der majestätischen Leichenfliege", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 70\n\n\"Nur die Truppen von Maldraxxus würden eine Leichenfliege als \"majestätisch\" bezeichnen.\"\nPakt:\nNekrolords\nVerkäufer:\nSu Zettai\nZone:\nMaldraxxus\nKosten:\n7500" }
