entries[186520] = { ["name"] = "Kiste mit Spieltestausrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erschafft Waffen und Schmuckstücke für Eure Charakterklasse sowie Gold und wichtige Verbrauchsgüter. Erfordert 20 freie Plätze im Inventar. Gegenstand wird bei Verwendung NICHT verbraucht. Ihr könnt Euch bei Bedarf erneut versorgen." }
entries[186521] = { ["name"] = "Kostenloser Ruhm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt Euch 1 Ruhmstufe, bis zu 80, falls Ihr einen Pakt gewählt habt." }
entries[186522] = { ["name"] = "Vertrag: Vorstoß des Todes", ["text"] = "Benutzen: Schließt einen Vertrag mit dem Vorstoß des Todes ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigt Vorstoß des Todes\n- Freundlich" }
