entries[186562] = { ["name"] = "Fesselrückenplatte des Folterers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[186563] = { ["name"] = "Speer des Pfählers", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n55 - 103 Schaden Geschwindigkeit 3.60\n(21.9 Schaden pro Sekunde)\n+29 Beweglichkeit\n+44 Ausdauer\nErhöht Eure kritische Trefferwertung um + 20.\n+ 38 Vielseitigkeit\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
