entries[186635] = { ["name"] = "Erinnerung an sündhafte Freuden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSündhafte Freuden Runenschnitzmacht Sofort\nWenn Ihr [ Arkan : 'Freizaubern' ] [ Feuer : eine Aufladung von 'Feuerschlag' /\n\nFrost\n'Hirnfrost' ] verbraucht, wird die Abklingzeit von 'Spiegel der Qual' um 4 Sek. verringert. Wenn 'Spiegel der Qual' gebannt wird, wird die Abklingzeit um 45 Sek. verringert.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Magier" }
entries[186636] = { ["name"] = "Käfig voller Schlundratten", ["text"] = "Torghast, Turm der Verdammten\nBenutzen: Entfesselt eine Schlundrattenbrut, die auf Befehl hin angreift. (5 Min Abklingzeit)\n\"Gleich mehrere Schlundratten blicken Euch voller Hoffnung durch die Stäbe an.\"" }
entries[186637] = { ["name"] = "Gleitscheibe von Tazavesh", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Mittler aller Art benutzen diese Gleiter, um durch Tazavesh und zu ähnlichen nahegelegenen Außenposten zu reisen. Auch Waren lassen sich damit transportieren.\"\nErfolg:\nGut gefälscht ist halb gewonnen\nKategorie:\nDungeon von Shadowlands" }
entries[186638] = { ["name"] = "Gleitscheibe des Kartellmeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die reichsten Kartellführer können sich die Metalle leisten, die für die Herstellung der Gleitscheibe des Kartellmeisters benötigt werden.\"\nBeute von:\nSo'leah\nZone:\nTazavesh, der Verhüllte Markt" }
entries[186639] = { ["name"] = "Gleitscheibe des Treuhänders Xy", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Kartell Xy handelt mit allerlei Währungen, doch keine davon ist ihrem inneren Zirkeln mehr Wert als Loyalität.\"\nQuelle:\n[ZENSIERT]" }
entries[186640] = { ["name"] = "Vandals Gleitscheibe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein seltener, speziell angepasster Gleiter, der besonders bei heimlichen Treffen zum Einsatz kommt. Er ist so leise, dass er kaum auszumachen ist, was ihn zu einem beliebten Werkzeug jener macht, die aus den Schatten heraus arbeiten.\"\nFraktion:\nVandalen der Manaschmiede\nRuhmstufe:\n8\nOrt:\nSchattenpunkt" }
entries[186641] = { ["name"] = "Harnisch des gezähmten Zerfleischers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Um Verschlinger zu zähmen, braucht man nur ein wenig Anima und eine Menge Geduld. Und eine Menge Heiltränke.\"\nBeute von:\nVorräte des Archivarskodex\nZone:\nKorthia" }
entries[186642] = { ["name"] = "Zügel von Rache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Sylvanas verlor einen Teil ihrer selbst, als Arthas ihr das Leben nahm, und die Dunkelheit in ihr wuchs an, um die Leere auszufüllen.\"\nBeute von:\nFürstin Sylvanas Windläufer\nZone:\nSanktum der Herrschaft\nSchwierigkeitsgrad:\nMythisch" }
entries[186643] = { ["name"] = "Zügel der Wanderin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese neugierige und wissbegierige Hirschkuh will ihren Besitzer nicht beunruhigen, aber sie lässt sich eben leicht ablenken. Besonders bei all den neuen Dingen, die es in Korthia zu sehen gibt.\"\nZone:\nKorthia" }
entries[186644] = { ["name"] = "Beryllsplitterfell", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Splitterfelle können sich gut im Unterholz verstecken und gezähmte Exemplare sind besonders selten.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia" }
entries[186645] = { ["name"] = "Blutrotes Splitterfell", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Korthia in den Schlund gezogen wurde, überlebten nur wenige besonders widerstandsfähige Arten.\"\nBeute von:\nMalbog\nZone:\nKorthia" }
entries[186646] = { ["name"] = "Finsterpranke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Finsterpranke ist ein älteres Splitterfell und trat den Korthianern zumeist recht zahm und freundlich gegenüber. Man glaubte, er sei in der Katastrophe verloren gegangen.\"\nZone:\nKorthia" }
entries[186647] = { ["name"] = "Bernsteinsplitterfell", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Vorstoß des Todes\n- Respektvoll\n\n\"Die leuchtenden Farben der korthianischen Wildtiere deuten darauf hin, dass ihnen entweder nur wenige Raubtiere auflauern oder sie sich zu wehren wissen.\"\nVerkäufer:\nHerzogin Mynx\nZone:\nKorthia\nFraktion:\nVorstoß des Todes - Respektvoll\nKosten:\n5.000" }
entries[186648] = { ["name"] = "Segelnde Klingenschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Der Archivarskodex\n- Stufe 6\n\n\"Die Haut der Klingenschwinge ist einerseits leicht, was ihr das Fliegen ermöglicht, aber andererseits auch recht robust, wodurch sie den Weg in den Schlund zu überleben vermag.\"\nVerkäufer:\nArchivar Roh-Suir\nZone:\nKorthia\nFraktion:\nDer Archivarskodex - Stufe 6\nKosten:\n5000" }
entries[186649] = { ["name"] = "Grimmige Klingenschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Klingenschwingen halten sich im Allgemeinen von anderen korthianischen Spezies fern, aber mit etwas Zeit und Geduld lassen auch sie sich zähmen.\"\nBeute von:\nVorräte des Vorstoßes des Todes\nZone:\nKorthia" }
entries[186650] = { ["name"] = "Vorräte des Vorstoßes des Todes", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186651] = { ["name"] = "Dämmerlichtklingenschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Klingenschwingen sind in ganz Korthia beheimatet. Sie bauen ihre Nester auf hohen Hügeln und in Bäumen.\"\nZone:\nKorthia" }
entries[186652] = { ["name"] = "Granatklingenschwinge", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Korthia war einst für seine leuchtend roten Blumen bekannt. Von mehreren Wildtieren weiß man, dass sie diese verzehrten oder sich darin wälzten, um eine leuchtend rote Färbung anzunehmen.\"\nBeute von:\nReliwik der Trotzige\nZone:\nKorthia" }
entries[186653] = { ["name"] = "Armschiene von Hrestimorak", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Der niederträchtige Verrat von Hrestimorak, der ihn auf Kosten seines Volkes an die Macht brachte, ist fast schon legendär. Als ihm die Verdammnis im Schlund drohte, versuchte er, den Kerkermeister zu stürzen... Ein törichtes Unterfangen, das ihm eine Ewigkeit voller Qualen einbrachte.\"\nErfolg:\nRuhm des herrschenden Schlachtzüglers\nZone:\nSanktum der Herrschaft" }
entries[186654] = { ["name"] = "Armreif von Salaranga", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Salaranga war die gerissenste ihrer Art und versteckte sich im Bestienlabyrinth. Sie griff den Verbannten mit einer Horde aus verbündeten Bestien an, auch wenn dies letztendlich keinen Unterschied machte.\"\nErfolg:\nDie Ketten durchbrechen\nZone:\nKorthia und der Schlund" }
entries[186655] = { ["name"] = "Zügel des schlundgebundenen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das Schicksal aller Pferdereittiere.\"\nErfolg:\nMakelloser Meister\nZone:\nTorghast, Turm der Verdammten" }
entries[186656] = { ["name"] = "Zügel des Sanktumdämmerstreitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur die mächtigsten Leutnants des Kerkermeisters erhalten diese Rösser, um durch die Hallen des Turms zu reiten.\"\nBeute von:\nDie Neun\nZone:\nSanktum der Herrschaft" }
entries[186657] = { ["name"] = "Zügel des seelengebundenen Dämmerstreitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ve'nari hat viele Methoden, im Schlund herumzuschleichen und die Pläne des Kerkermeisters zu durchkreuzen, darunter auch das Binden seiner Diener.\"\nBeute von:\nGeheimnisvolles Geschenk von Ve'nari\nZone:\nDer Schlund" }
entries[186659] = { ["name"] = "Zügel des gefallenen Streitrosses", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Schreie des Streitrosses hallen durch den Schlund, während es seinen endlosen Ritt durch das Land fortsetzt, immer auf der Suche nach einem Ausweg aus den endlosen Qualen, denen es ausgesetzt ist.\"\nBeute von:\nGefallenes Streitross\nZone:\nDer Schlund" }
