entries[186671] = { ["name"] = "Vantusrunentechnik: Sanktum der Herrschaft", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Vantusrune: Sanktum der Herrschaft herstellt.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:\nVantusrune: Sanktum der Herrschaft\nBenutzen: Stellt Euch auf die Energien des anvisierten Schlachtzugsbosses aus dem Sanktum der Herrschaft ein, was Eure Vielseitigkeit um 1875 erhöht, während Ihr diesen Boss bekämpft. Dieser Effekt hält eine ganze Woche lang an.\n\nIhr könnt nur eine Vantusrune pro Woche nutzen.\nVerkaufspreis:\nBenötigt Leuchtende Tinte (10), Umbraltinte (10), Stille Tinte , Dunkles Pergament" }
entries[186672] = { ["name"] = "Vergängliche Schwingen", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Springt auf vergänglichen Schwingen vorwärts, die die Fallgeschwindigkeit 10 Sek. lang verringern. Springt dann zu einer Position in der Nähe. (6 Sek. Abklingzeit)" }
entries[186673] = { ["name"] = "Erinnerung an die Seelenaffinität", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSeelenaffinität Stufe 80 Runenschnitzmacht Sofort\nIhr und die Euch verwandte Seele erhaltet jeweils einen Bonus auf einen Sekundärwert, der von ihrem Pakt abhängt. Für Eure verwandte Seele wird dieser Bonus halbiert, jedoch werden beide Boni verdoppelt, während Eure Verbindung ermächtigt ist.\n\nKyrianer : Meisterschaft um 571 erhöht.\nNachtfae : Tempo um 6% erhöht.\nVenthyr : Kritische Trefferchance um 6% erhöht.\nNekrolords : Vielseitigkeit um 6% erhöht.\nRunenschnitzen: Hals, Schulter\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Druide" }
entries[186676] = { ["name"] = "Erinnerung an die toxische Offensive", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nToxische Offensive Runenschnitzmacht Sofort\nWenn 'Sepsis' bei Eurem Ziel abläuft, erhaltet Ihr für 10 Sek. [ Meucheln : 'Adrenalinrausch' und 'Schattenklingen' ] [ Gesetzlosigkeit : 'Schattenklingen' und belegt Euer aktuelles Ziel für diese Dauer mit 'Vendetta' ] [ Täuschung : 'Adrenalinrausch' und belegt Euer aktuelles Ziel für diese Dauer mit 'Vendetta' ]\nRunenschnitzen: Brust, Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke" }
entries[186677] = { ["name"] = "Metallischer Sockel", ["text"] = "Verkaufspreis:" }
entries[186678] = { ["name"] = "Vorrat schlundgeschmiedeter Waffen", ["text"] = "Torghast, Turm der Verdammten\nBenutzen: Schlundgeschmiedete Waffen stehen Euch 2 Min. lang im Kampf bei. (5 Min Abklingzeit)\n\"Diese Waffen scheinen einen eigenen Willen zu besitzen.\"" }
entries[186679] = { ["name"] = "Schriftrolle der Herrschaft", ["text"] = "Torghast, Turm der Verdammten\nBenutzen: Lässt Euch ein gegnerisches Nicht-Eliteziel für 2 Min. kontrollieren. Wenn die Rune schwindet, explodiert das kontrollierte Ziel und fügt allen Zielen in der Nähe Schaden zu. (5 Min Abklingzeit)\n\"Starrt besser nicht zu lange auf die Runen.\"" }
entries[186680] = { ["name"] = "Goldgefüllter Stiefel", ["text"] = "Wird beim Aufheben gebunden\n\"Vergesst nicht, dass er voller Gold ist, sonst verletzt Ihr Euch vielleicht noch die Zehen.\"\n<Zum Öffnen rechtsklicken>" }
entries[186684] = { ["name"] = "Erinnerungen an sonnigere Zeiten", ["text"] = "Benutzen: Erinnert Euch an sonnigere Zeiten in Oribos, bevor die Macht des Schlunds anwuchs. Hält 168 Stunden lang an.\n\"Richtet absolut nichts gegen die aufziehende Dunkelheit aus, lässt sie aber gleich viel hübscher erscheinen.\"\nVerkaufspreis:" }
entries[186685] = { ["name"] = "Reliktfragment", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nBenutzen: Gebt die Reliktfragmente bei Archivar Roh-Suir im Reliquiar der Erinnerung ab und erzeugt 1 katalogisierte Forschung.\n\"Uralte Symbole sind immer noch auf der Oberfläche dieser Fragmente zu erkennen.\"\nVerkaufspreis:" }
entries[186686] = { ["name"] = "Bleiche Orakelknochen", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Befragt die Knochen, um Eure Zukunft zu erfahren. (15 Min Abklingzeit)\n\"Eine Sammlung kleiner Knochen, die mit geschnitzten Symbolen verziert sind und dem Benutzer einen Blick in die Zukunft ermöglichen.\"" }
entries[186687] = { ["name"] = "Erinnerung an himmlische Geister", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nHimmlische Geister Runenschnitzmacht Sofort\nVerringert die Abklingzeit von 'Konvokation der Geister' um 50% und die Dauer um 25%. 'Konvokation der Geister' hat eine erhöhte Chance, einen außergewöhnlichen Zauber oder eine außergewöhnliche Fähigkeit einzusetzen.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Druide" }
entries[186688] = { ["name"] = "Goldgefüllter Wascheimer", ["text"] = "Wird beim Aufheben gebunden\n\"Durch den Henkel lässt sich das Gold ganz einfach damit transportieren.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186689] = { ["name"] = "Erinnerung an zersplitterte Elemente", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nZersplitterte Elemente Runenschnitzmacht Sofort\nJeder zusätzliche Einsatz von 'Blitzschlag' , der von 'Urzeitliche Welle' erzeugt wird, erhöht Euer Tempo 12 Sek. lang um 10%.\nRunenschnitzen: Hals, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt." }
entries[186690] = { ["name"] = "Goldgefülltes Fass", ["text"] = "Wird beim Aufheben gebunden\n\"Rendel war ziemlich sauer, als er sein Braufass dazu benutzen musste, das viele Gold zu lagern.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186691] = { ["name"] = "Goldgefüllter Beutel", ["text"] = "Wird beim Aufheben gebunden\n\"Der Beutel wurde durch zusätzliche Nähte verstärkt, um all die Münzen halten zu können.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186692] = { ["name"] = "Goldgefüllter Helm", ["text"] = "Wird beim Aufheben gebunden\n\"Achtung: Umgekehrt halten, bis Ihr bereit seid, die Münzen herauszunehmen.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186693] = { ["name"] = "Goldgefüllte Schubkarre", ["text"] = "Wird beim Aufheben gebunden\n\"Wenn Ihr eine Schubkarre braucht, um all Euer Gold zu transportieren, habt Ihr dann genug?\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186694] = { ["name"] = "Schattenhafte Tasche voller Erz", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Tasche voller Erz aus den Schattenlanden.\"\n<Zum Öffnen rechtsklicken>" }
entries[186695] = { ["name"] = "Entzückende Begleiterbandage", ["text"] = "Questgegenstand\nBenutzen: Verhilft einem verletzten Verbündeten wieder auf die Beine... gewissermaßen." }
entries[186696] = { ["name"] = "Gunstgroschen von Kartell Ta", ["text"] = "Questgegenstand\n\"Eine symbolische Münze zum Beweis, dass eine Gunst mit einer anderen vergolten wurde.\"" }
entries[186697] = { ["name"] = "Blütenexplosion", ["text"] = "Benutzen: Bedeckt Eure Freunde mit ein wenig grüner Farbe! Spaß für Groß und Klein! (3 Min Abklingzeit)\n5 Aufladungen" }
entries[186698] = { ["name"] = "Fackelexplosion", ["text"] = "Benutzen: Bedeckt Eure Freunde mit ein wenig oranger Farbe! Spaß für Groß und Klein! (3 Min Abklingzeit)\n5 Aufladungen" }
entries[186699] = { ["name"] = "Witwenexplosion", ["text"] = "Benutzen: Bedeckt Eure Freunde mit ein wenig violetter Farbe! Spaß für Groß und Klein! (3 Min Abklingzeit)\n5 Aufladungen" }
entries[186700] = { ["name"] = "Markexplosion", ["text"] = "Benutzen: Bedeckt Eure Freunde mit ein wenig grauer Farbe! Spaß für Groß und Klein! (3 Min Abklingzeit)\n5 Aufladungen" }
entries[186701] = { ["name"] = "Ruhmexplosion", ["text"] = "Benutzen: Bedeckt Eure Freunde mit ein wenig gelber Farbe! Spaß für Groß und Klein! (3 Min Abklingzeit)\n5 Aufladungen" }
entries[186702] = { ["name"] = "Bleiche Knochenflöte", ["text"] = "Spielzeug\nBenutzen: Spielt eine unheimliche Melodie, die alle in Eurer Umgebung zum Tanzen verleitet. (10 Min Abklingzeit)\n\"Eine Knochenflöte aus dem Land der Toten? Ist ja überhaupt nicht unheilschwanger.\"" }
entries[186703] = { ["name"] = "Goldener Kelch", ["text"] = "Wird beim Aufheben gebunden\n\"Der Kelch allein scheint schon eine Menge Gold wert zu sein.\"\nVerkaufspreis:" }
entries[186704] = { ["name"] = "Zwielichttee", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 30000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben." }
entries[186705] = { ["name"] = "Goldgefüllter Kelch", ["text"] = "Wird beim Aufheben gebunden\n\"Rendel hat einen Haufen Münzen aus seinem riesigen Vorrat geschaufelt, um den Kelch damit zu füllen.\"\n<Zum Öffnen rechtsklicken>" }
entries[186706] = { ["name"] = "Goldgefüllter Hut", ["text"] = "Wird beim Aufheben gebunden\n\"Das Gewicht der vielen Münzen in diesem Hut stellt das Garn, aus dem er gemacht ist, buchstäblich auf eine Zerreißprobe.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186707] = { ["name"] = "Goldgefüllte Kiste", ["text"] = "Wird beim Aufheben gebunden\n\"Die Kiste ist so vollgepackt mit Münzen, dass sie schon durch den Spalt zwischen dem Deckel und der Kiste herausfallen.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186708] = { ["name"] = "Goldgefüllter Pinselbecher", ["text"] = "Wird beim Aufheben gebunden\n\"Normalerweise stellt niemand irgendwelche Fragen zu den seltsamen Interessen von Gräbern. Erst recht nicht, wenn ein Gräber so unverzichtbare Dienste anbietet wie die Reparatur von Ausrüstung.\"\n<Zum Öffnen rechtsklicken>\nVerkaufspreis:" }
entries[186710] = { ["name"] = "Erinnerung an die Gehorsamen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGehorsam Runenschnitzmacht Sofort\n'Geißelung' erhöht zusätzlich Eure Vielseitigkeit um 0.5%. Jeder Combopunkt, der verbraucht wird, während 'Geißelung' aktiv ist, verringert die Abklingzeit der Fähigkeit um 1 Sek. (100ms Abklingzeit)\nRunenschnitzen: Kopf, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke" }
entries[186712] = { ["name"] = "Erinnerung an den Todesstachel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTodesstachel Runenschnitzmacht Sofort\n'Gezackter Knochenstachel' hat 2 zusätzliche Aufladungen und verschießt 1 zusätzlichen Knochenstachel auf Gegner in der Nähe.\nRunenschnitzen: Handgelenk, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke" }
entries[186713] = { ["name"] = "Nilganihmahts Steuerungsring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Von allen Riesen, die es wagten, dem Kerkermeister zu trotzen, war Nilganihmaht der arroganteste. Für sein Vergehen wurde die abgetrennte Hand des Riesen in einem Schleier der Qualen verborgen und die Ringe, die sie zurückbringen könnten, wurden über den ganzen Schlund verstreut.\"\nZone:\nDer Schlund" }
entries[186714] = { ["name"] = "Untersuchungsbericht: Allsehender Kristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch dauerhaft, Kreaturen zu sehen und zu finden, die Reliktfragmente tragen.\nErfordert Forschungsstufe 2 beim Archivarskodex.\n\"Es ist Roh-Suir gelungen, die Forschung zum allsehenden Kristall zu replizieren, sodass Ihr nun einen dieser Kristalle an einem Leitstab befestigen könnt, um andere Relikte aufzuspüren.\"" }
entries[186715] = { ["name"] = "Untersuchungsbericht: Verbesserte Legierungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 10 aufzuwerten.\n\"Die Analyse der Auswirkungen der Herrschaftsmagie auf Gegenstände aus Korthia und dem Schlund hat zur Entwicklung verbesserter Legierungen geführt, durch die wir unsere eigenen Gegenstände widerstandsfähiger und mächtiger machen können.\"" }
entries[186716] = { ["name"] = "Untersuchungsbericht: Uralte Schreine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch, mit Schwertern in der Nähe von uralten Schreinen zu interagieren, die Euch auf ansonsten nicht zugängliche Reliktschätze zugreifen lassen.\nErfordert Forschungsstufe 5 beim Archivarskodex.\n\"Weitere Untersuchungen der mysteriösen Chiffre des Erkenntnis, die Ihr aus dem Riss geborgen habt, haben es uns ermöglicht, die Wechselwirkung mit den uralten Schreinschwertern zu verstehen, die man in ganz Korthia findet.\"" }
entries[186717] = { ["name"] = "Untersuchungsbericht: Adaptive Legierungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 5 aufzuwerten.\nErfordert Forschungsstufe 6 beim Archivarskodex und Ruhmstufe 61 oder höher.\n\"Weitere Untersuchungen im Zuge der Reliktwiederbeschaffung haben zur Entdeckung neuer adaptiver Legierungen geführt, die es uns ermöglichen werden, die Macht der von Herrschaftsmagie berührten Objekte in Korthia und im Schlund zu erhöhen.\"" }
entries[186718] = { ["name"] = "Reparaturset für Teleporter", ["text"] = "Wird beim Aufheben gebunden\nErfordert Forschungsstufe 3 beim Archivarskodex.\n\"Eine Sache scheint wohl überall im Universum gleich zu sein: Schon so lang die Zeit vergeht, wird stets nach rechts fest zugedreht. Wird benötigt, um uralte Teleporter in Korthia zu reparieren, sodass Ihr Zugang zu verborgenen Kammern erhaltet.\"" }
entries[186721] = { ["name"] = "Abhandlung: Die Fülle an Relikten in den Schattenlanden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Euch dauerhaft die Fähigkeit, Relikte zu finden, die Euch Bonusruf bei den Zonenfraktionen der Schattenlande gewähren, wenn Ihr in ihren Reichen Weltquests und tägliche Quests abschließt, Schätze plündert oder seltene Kreaturen besiegt.\nErfordert Forschungsstufe 6 beim Archivarskodex." }
entries[186722] = { ["name"] = "Abhandlung: Das Studium der Anima und die Nutzung jedes Tropfens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Euch dauerhaft die Fähigkeit, 25 zusätzliche Anima zu finden, wenn Ihr in den Schattenlanden Weltquests und tägliche Quests abschließt, Schätze plündert oder seltene Kreaturen besiegt.\nErfordert Forschungsstufe 5 beim Archivarskodex." }
entries[186724] = { ["name"] = "Technik: Vertrag: Vorstoß des Todes", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Vertrag: Vorstoß des Todes herstellt.\nBenötigt Inschriftenkunde der Schattenlande (60)\nBenötigt Vorstoß des Todes\n- Respektvoll\nVerkaufspreis:\nVertrag: Vorstoß des Todes\nBenutzen: Schließt einen Vertrag mit dem Vorstoß des Todes ab, der Euch jedes Mal Ruf bei dieser Fraktion gewährt, wenn Ihr Weltquests in den Schattenlanden abschließt.\nBenötigt Vorstoß des Todes\n- Freundlich\nBenötigt Leuchtende Tinte , Umbraltinte , Dunkles Pergament" }
entries[186725] = { ["name"] = "Knochenmehlbrot", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben." }
entries[186726] = { ["name"] = "Poröser Zuckerkiesel", ["text"] = "Benutzen: Genießt eine köstliche Leckerei.\n\"Absolut frei von jeglichem Nährwert.\"" }
entries[186727] = { ["name"] = "Siegelbrecherschlüssel", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Schlüssel, mit dem sich jedes Herrschaftssiegel brechen lässt.\"" }
entries[186730] = { ["name"] = "Haustierbedarf", ["text"] = "Questgegenstand\n\"Verwertbarer Haustierbedarf.\"" }
entries[186731] = { ["name"] = "Reparierter Rissschlüssel", ["text"] = "Wird beim Aufheben gebunden\nAnlegen: Ermöglicht Euch, ein Rissportal in Korthia zu betreten und 15 Min. darin zu bleiben.\nErfordert Forschungsstufe 4 beim Archivarskodex.\n\"Seltsame Mächte erfüllen diesen Stein. Er summt förmlich vor Energie in Eurer Hand und Ihr vernehmt ein Flüstern wie aus dem Jenseits.\"\nVerkaufspreis:" }
entries[186732] = { ["name"] = "Kiste der Zahllosen Dinge", ["text"] = "Questgegenstand\n\"Die Macht vieler Reiche durchströmt diese aus Metall und Magie gefertigte Kiste.\"" }
entries[186733] = { ["name"] = "Entzückender Begleiterrufer", ["text"] = "Questgegenstand\n\"Erregt mit einem sanften Pfeifen die Aufmerksamkeit Eures Haustiers.\"" }
