entries[186992] = { ["name"] = "Formel: Anima-lische Leine", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine anima-lische Leine herstellt.\nBenötigt Verzauberkunst der Schattenlande (40)\n\nAnima-lische Leine\nEinzigartig\nSpielzeug\nBenutzen: Eine Animaleine.\n80 ( 80)\nVerkaufspreis:\nBenötigt Seelenstaub (2), Heiliger Splitter (2)" }
entries[186993] = { ["name"] = "Vorlage: Poröse Steinstatue", ["text"] = "Einzigartig\nBenutzen: Lehrt Euch, wie man eine poröse Steinstatue herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(50)\nVerkaufspreis:\nPoröse Steinstatue\nBenutzen: Stellt eine poröse Steinstatue auf den Boden, die Euch eine kurze Zeit lang heilen wird, bevor ihre Kräfte schwinden. (5 Min Abklingzeit)\nBenötigt Juwelierskunst der Schattenlande\n(50)\nVerkaufspreis:\nBenötigt Poröser Stein (5)" }
entries[186994] = { ["name"] = "Vorlage: Verdunkelte Steinstatue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine verdunkelte Steinstatue herstellt.\nBenötigt Juwelierskunst der Schattenlande\n(100)\nVerkaufspreis:\nVerdunkelte Steinstatue\nBenutzen: Stellt eine verdunkelte Steinstatue auf den Boden, die Euch eine kurze Zeit lang heilen wird, bevor ihre Kräfte schwinden. (5 Min Abklingzeit)\nBenötigt Juwelierskunst der Schattenlande\n(100)\nVerkaufspreis:\nBenötigt Verdunkelter Stein (5)" }
entries[186995] = { ["name"] = "Muster: Schleierstoffhandtuch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Schleierstoffhandtuch herstellt.\nBenötigt Schneiderei der Schattenlande (5)\n\nSchleierstoffhandtuch\nBenutzen: Entfernt Blut, Schleim, Staub... im Prinzip alles! (10 Sek. Abklingzeit)\n\"Sauberkeit ist der Weg zur Unsterblichkeit.\"\nVerkaufspreis:\nBenötigt Schleierstoff (3)" }
entries[186997] = { ["name"] = "Wappenrock des Vorstoßes des Todes", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt Vorstoß des Todes\n- Ehrfürchtig" }
entries[186998] = { ["name"] = "Muster: Bleiche Orakelknochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man bleiche Orakelknochen herstellt.\nBenötigt Lederverarbeitung der Schattenlande (50)\nVerkaufspreis:\nBleiche Orakelknochen\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Befragt die Knochen, um Eure Zukunft zu erfahren. (15 Min Abklingzeit)\n\"Eine Sammlung kleiner Knochen, die mit geschnitzten Symbolen verziert sind und dem Benutzer einen Blick in die Zukunft ermöglichen.\"\nBenötigt Bleicher Knochen (14)" }
entries[186999] = { ["name"] = "Muster: Bleiche Knochenflöte", ["text"] = "Einzigartig\nBenutzen: Lehrt Euch, wie man eine bleiche Knochenflöte herstellt.\nBenötigt Lederverarbeitung der Schattenlande (75)\nVerkaufspreis:\nBleiche Knochenflöte\nSpielzeug\nBenutzen: Spielt eine unheimliche Melodie, die alle in Eurer Umgebung zum Tanzen verleitet. (10 Min Abklingzeit)\n\"Eine Knochenflöte aus dem Land der Toten? Ist ja überhaupt nicht unheilschwanger.\"\nBenötigt Bleicher Knochen (20), Penumbrafaden (3)" }
entries[187000] = { ["name"] = "Muster: Wieselndes Leckerli", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man ein Aufziehskelett herstellt.\nBenötigt Lederverarbeitung der Schattenlande (100)\nVerkaufspreis:\nWieselndes Leckerli\nSpielzeug\nBenutzen: Setzt einen kleinen knochentragenden Golem ab, den Euer Haustier 30 Sek. lang jagen kann. (10 Min Abklingzeit)\nVerkaufspreis:\nBenötigt Bleicher Knochen (18), Unsterblichkeitssplitter (3)" }
entries[187001] = { ["name"] = "Schickes Begleiterhalsband", ["text"] = "Questgegenstand\n\"Das modische Accessoire für den Begleiter von Welt.\"" }
entries[187002] = { ["name"] = "Köstlicher Begleiterkeks", ["text"] = "Questgegenstand\n\"Ein wirklich lecker aussehender Keks. Ich bin sicher, der schmeckt nicht nur Begleitern.\"" }
entries[187003] = { ["name"] = "Begleiterplüschtier", ["text"] = "Questgegenstand\n\"Ein zukünftiges Opfer des unbändigen Spieltriebs eines Begleiters.\"" }
entries[187004] = { ["name"] = "Kauknochen", ["text"] = "Questgegenstand\n\"Noch niemals vergraben.\"" }
entries[187005] = { ["name"] = "Begleiterzaubererhut", ["text"] = "Questgegenstand\n\"Welchem Haus...tier wollt Ihr diesen Hut zuweisen?\"" }
entries[187006] = { ["name"] = "Rezept: Zwielichttee", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man einen Zwielichttee herstellt.\nBenötigt Kochkunst der Schattenlande (75)\nVerkaufspreis:\nZwielichttee\nBenutzen: Stellt im Verlauf von 20 Sek. ( 30000 / 5 * 20) Mana wieder her. Ihr müsst beim Trinken sitzen bleiben.\nBenötigt Zwielichtborke (3), Reichhaltige Grasfressermilch (3)" }
entries[187007] = { ["name"] = "Rezept: Knochenmehlbrot", ["text"] = "Einzigartig\nBenutzen: Lehrt Euch, wie man ein Knochenmehlbrot herstellt.\nBenötigt Kochkunst der Schattenlande (35)\nVerkaufspreis:\nKnochenmehlbrot\nBenutzen: Stellt im Verlauf von 20 Sek. ( 22500 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\nBenötigt Bleicher Knochen (3), Reichhaltige Grasfressermilch (2), Transplanare Gewürzmischung" }
entries[187008] = { ["name"] = "Rezept: Poröser Zuckerkiesel", ["text"] = "Einzigartig\nBenutzen: Lehrt Euch, wie man einen porösen Zuckerkiesel herstellt.\nBenötigt Kochkunst der Schattenlande (25)\nVerkaufspreis:\nPoröser Zuckerkiesel\nBenutzen: Genießt eine köstliche Leckerei.\n\"Absolut frei von jeglichem Nährwert.\"\nBenötigt Poröser Stein (3), Zwielichtborke , Transplanare Gewürzmischung (3)" }
