entries[187047] = { ["name"] = "Tarnung des Wechselbalgs", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Oberfläche dieser Maske verändert sich kontinuierlich. Während Euer Blick auf ihr ruht, könnt Ihr Dutzende verschiedener Antlitze erkennen.\"" }
entries[187051] = { ["name"] = "Vergessene Feder", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schenkt Eurem Kampfhaustier die Macht der Val'kyr, sodass es neben Euch herfliegen kann. (10 Sek. Abklingzeit)" }
entries[187052] = { ["name"] = "Der Netherstern", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Summt leise vor potenzieller Energie.\"" }
entries[187054] = { ["name"] = "Verlorenes Klingenschwingenei", ["text"] = "Wird beim Aufheben gebunden\n\"Der Verschlinger hat entweder ein Klingenschwingennest geplündert oder es ist einfach herausgefallen. Vielleicht zeigt sich die Matriarchin ja erkenntlich, wenn Ihr es zu seinem Nest zurückbringt.\"" }
entries[187055] = { ["name"] = "Beutel voller Runenmarken", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine einzige einsame Marke ist im Beutel übrig.\"" }
entries[187056] = { ["name"] = "Die verschlingende Kälte", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Schwert\n55 - 92 Schaden Geschwindigkeit 2.60\n(28.3 Schaden pro Sekunde)\n+25 Stärke\n+37 Ausdauer\nErhöht Eure kritische Trefferwertung um + 35.\n+ 14 Vielseitigkeit\nHaltbarkeit 110 / 110\nVerkaufspreis:" }
entries[187057] = { ["name"] = "Splitter von Bek", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Bek (1)\nIm Schlund wird Euer Schaden um ( 6046 / 100)% erhöht, wenn Ihr mindestens 50% mehr Gesundheit habt als Euer Ziel.\nVerkaufspreis:" }
entries[187059] = { ["name"] = "Splitter von Jas", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Jas (1)\nErhöht im Schlund Eure erhaltene Heilung um ( 302 / 10)% und Eure maximale Gesundheit um 44844 .\nVerkaufspreis:" }
entries[187061] = { ["name"] = "Splitter von Rev", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Blutsplitter von Rev (1)\nIm Schlund ist Euer Lebensraub um 1209 erhöht.\nVerkaufspreis:" }
entries[187063] = { ["name"] = "Splitter von Cor", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Cor (1)\nWenn Ihr im Schlund einen Gegner angreift, dem Ihr zuvor noch keinen Schaden zugefügt habt, wird Euer Schaden 20 Sek. lang um ( 6046 / 100)% erhöht.\nVerkaufspreis:" }
entries[187065] = { ["name"] = "Splitter von Kyr", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Kyr (1)\nGewährt im Schlund alle 5 Sek. ( 98657 * (1 + Vielseitigkeit)) Absorption, bis zu maximal 493286 .\nVerkaufspreis:" }
entries[187071] = { ["name"] = "Splitter von Tel", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Tel (1)\nIm Schlund lassen Eure kritischen Treffer einen Verbündeten in der Nähe die nächsten ( 25561 * (1 + Vielseitigkeit)) Schaden absorbieren, die er innerhalb von 6 Sek. erleidet.\nVerkaufspreis:" }
entries[187073] = { ["name"] = "Splitter von Dyz", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Dyz (1)\nWenn Ihr im Schlund einem Ziel Schaden zufügt, wird Euer diesem Ziel zugefügter Schaden 4 Sek. lang um ( 1008 / 100)% erhöht. Bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[187075] = { ["name"] = "Kiste mit rasselnden Ketten", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Entfesselt den Minigrue, der einige Spielzeuge in der Nähe zerstören wird. (30 Min Abklingzeit)" }
entries[187076] = { ["name"] = "Splitter von Oth", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Oth (1)\nIm Schlund ist Eure Geschwindigkeit ist um 1209 erhöht.\nVerkaufspreis:" }
entries[187077] = { ["name"] = "Verpackte Seelenasche", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Öffnen, um 250 Seelenasche zu erhalten.\nIhr müsst die 9. Ebene von Torghast freigeschaltet haben.\n\"Für einfachen Transport verpackt. Eine beträchtliche Menge Seelenasche ging aufgrund ihrer flüchtigen Natur verloren.\"" }
entries[187079] = { ["name"] = "Splitter von Zed", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Zed (1)\nIm Schlund haben Eure hilfreichen Zauber und Fähigkeiten eine Chance, Eurem Ziel eine unheilige Aura zu gewähren, die Gegnern in der Nähe 10 Sek. lang alle 2 Sek. 24814 Gesundheit entzieht.\nVerkaufspreis:" }
