entries[187101] = { ["name"] = "Silberne Schulterschilde", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187103] = { ["name"] = "Ewiglebende Statuette", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Die Ereignisse, die diese Statuette miterlebt hat, spotten jeder Vorstellungskraft. Man könnte viel daraus lernen, wenn sie nur nicht so doppelzüngig wäre.\"" }
entries[187104] = { ["name"] = "Obelisk düsterer Kunde", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"In der Nähe des Obelisken flüstert eine Stimme in Eurem Kopf Euch liebliche Lügen und erzürnende Wahrheiten zu.\"" }
entries[187105] = { ["name"] = "Erinnerung an den Blick der Agonie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBlick der Agonie Runenschnitzmacht Sofort\n'Sündhaftes Brandzeichen' verursacht 10% mehr Schaden und Schaden durch [ Verwüstung : 'Augenstrahl' /\n\nRachsucht\n'Dämonische Verwüstung' ] erhöht die Dauer von 'Sündhaftes Brandzeichen' um 0.75 Sek.\nRunenschnitzen: Kopf, Beine\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger" }
entries[187106] = { ["name"] = "Erinnerung an die göttliche Resonanz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGöttliche Resonanz Runenschnitzmacht 30 Meter Reichweite\nSofort\nNach dem Einsatz von 'Göttlicher Glockenschlag' setzt Ihr sofort und dann alle 5 Sek. [ Schutz : 'Schild des Rächers' ] [ Heilig : 'Heiliger Schock' /\n\nVergeltung\n'Richturteil' ] ein. Dieser Effekt hält 15 Sek. lang an. (3s Abklingzeit)\nRunenschnitzen: Brust, Taille\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin" }
entries[187107] = { ["name"] = "Erinnerung an den pflichtgebundenen Hammer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nPflichtgebundener Hammer Runenschnitzmacht Sofort\nVergeltung\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Urteil des Templers' löst automatisch 'Göttlicher Sturm' aus.\n\nHeilig\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Licht der Morgendämmerung' aus.\n\nSchutz\n'Hammer des Bezwingers' erhält 1 zusätzliche Aufladung. Ein zusätzlicher Einsatz von 'Wort der Herrlichkeit' löst automatisch 'Schild der Rechtschaffenen' aus.\nRunenschnitzen: Kopf, Schulter, Finger\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin" }
entries[187109] = { ["name"] = "Erinnerung an das lodernde Gemetzel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nLoderndes Gemetzel Runenschnitzmacht Sofort\n'Die Jagd' hüllt Euch in 'Feuerbrandaura', wenn Ihr Euer Ziel erreicht, und Eure Beweglichkeit wird pro getroffenem Gegner 12 Sek. lang um 4% erhöht.\nRunenschnitzen: Schulter, Füße, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger" }
entries[187111] = { ["name"] = "Erinnerung an den blinden Glauben", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBlinder Glaube Runenschnitzmacht Sofort\n'Elysischer Erlass' spaltet zusätzlich 2 geringe Seelenfragmente ab und gewährt Euch für 20 Sek. 'Blinder Glaube'. Jedes geringe Seelenfragment, das Ihr aufzehrt, während 'Blinder Glaube' aktiv ist, gewährt Euch 10 Jähzorn und 1% Vielseitigkeit, bis zu maximal 20%.\nRunenschnitzen: Brust, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger" }
entries[187113] = { ["name"] = "Persönliche Kugelfessel", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Erstellt Eure persönliche Kugelfessel, die Ihr mit Euch herumschleppen könnt. (5 Min Abklingzeit)\n\"Es gibt viele andere, aber diese ist meine.\"\nVerkaufspreis:" }
entries[187115] = { ["name"] = "Brief der Schlundgebundenen", ["text"] = "Questgegenstand\n\"Einzelheiten zu den Befehlen des Kerkermeisters.\"" }
entries[187116] = { ["name"] = "Zielattrappe", ["text"] = "Benutzen: Bringt dauerhaft ein winziges Gerät an Eurem Gürtel an. Damit könnt Ihr einen Pappkameraden erstellen, der von den Gegnern angegriffen wird. (5 Min. Abklingzeit)\nVerkaufspreis:" }
entries[187117] = { ["name"] = "Azurblaue Seiten", ["text"] = "Questgegenstand\n\"Ausgerissene Seiten voller Energie.\"" }
entries[187118] = { ["name"] = "Erinnerung an den dämonischen Schwur", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDämonischer Schwur Runenschnitzmacht Sofort\nWenn der Dämon von 'Futter für die Flamme' explodiert, belegt er 5 Gegner in der Nähe für 5 Sek. mit 'Flammendes Brandmal'. Zusätzlich ist die Dauer von 'Zerschmetterte Seele' um 8 Sek. erhöht.\nRunenschnitzen: Taille, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Dämonenjäger" }
entries[187119] = { ["name"] = "Ring der Selbstreflexion", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Wenn man den in den Ring eingesetzten Edelstein aus einem schrägen Winkel ansieht, erblickt man ein schimmerndes Spiegelbild des Ringes.\"" }
entries[187120] = { ["name"] = "Blutheilungssplitter 1 - Rang 5", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nIm Schlund ist Euer Lebensraub um 1209 erhöht." }
entries[187123] = { ["name"] = "Ermächtigungsornament", ["text"] = "Wird beim Aufheben gebunden\n\"Benutzt dies, um den anvisierten Splitter der Herrschaft aufzuladen.\"" }
entries[187124] = { ["name"] = "Medaillon des Zorns", ["text"] = "Questgegenstand\n\"Wurde den Venthyr von Graf Denathrius selbst verliehen. Ermöglicht es dem Träger, teilweise über Revendreth zu herrschen.\"" }
entries[187126] = { ["name"] = "Weggeworfenes Tagebuch", ["text"] = "Questgegenstand\n\"Von Mittler Xevveth verfasst. Scheint wohl verlegt worden zu sein.\"" }
entries[187127] = { ["name"] = "Erinnerung an die strahlende Glut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nStrahlende Glut Runenschnitzmacht Sofort\nErhöht die Dauer von 'Ascheweihung' um 50%. Wenn Ihr den Effekt vorzeitig aufhebt, wird die Abklingzeit abhängig von der verbleibenden Dauer um bis zu 50% verringert.\nRunenschnitzen: Handgelenk, Hände, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin" }
entries[187128] = { ["name"] = "Spiondetektor", ["text"] = "Questgegenstand\nBenutzen: Ruft die Spionfängerkatze Fiona zu Hilfe. (6 Sek. Abklingzeit)" }
entries[187131] = { ["name"] = "Automainnereien", ["text"] = "Questgegenstand\n\"...schmierig?\"" }
entries[187132] = { ["name"] = "Erinnerung an die Jahreszeiten der Fülle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nJahreszeiten der Fülle Runenschnitzmacht Sofort\nDer Einsatz von 'Segen des Sommers' gewährt nach 10 Sek. 'Äquinoktium'.\n\nÄquinoktium: Erhöht die Effektivität von 'Segen des Sommers' 10 Sek. lang um 100%.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Paladin" }
entries[187133] = { ["name"] = "Bezaubernder kleiner Hut", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n\"Schenkt dies Eurem Gräberbutler, damit er die Möglichkeit erhält, einen Hexenhut zu tragen.\"" }
entries[187134] = { ["name"] = "Legierungskrümmender Facettierer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Fügt einem Gegenstand der Saison 2 von Shadowlands, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Halsketten, Armschienen, Gürtel und Ringe angewandt werden." }
entries[187136] = { ["name"] = "Untersuchungsbericht: Reliktuntersuchungstechniken", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig\nBenutzen: Ihr erhaltet 50% mehr Ruf beim Archivarskodex, wenn Ihr Relikte beim Archivar abgebt.\nErfordert Forschungsstufe 6 beim Archivarskodex.\n\"Durch die Verbesserung seiner Forschungstechniken ist der Archivar in der Lage, mehr Wissen über jedes Fragment zu erlangen, das ihm gebracht wird.\"" }
entries[187137] = { ["name"] = "Untersuchungsbericht: Reliktsuchtechniken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Euch eine Chance von 20%, beim Plündern von seltenen Gegnern und Schätzen in Korthia mehr Reliktfragmente zu finden.\n\"Zu wissen, wie man fehlende Relikte identifiziert, ist für unsere Bemühungen von entscheidender Bedeutung. Dieser Bericht umfasst daher Tipps und Tricks, die in manchen Fällen dabei helfen können, mehr Reliktfragmente aus gewöhnlichen Ressourcen zu gewinnen.\"" }
entries[187138] = { ["name"] = "Untersuchungsbericht: Erste Legierungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Ermöglicht Euch, Eure Gegenstände aus Korthia und dem Schlund auf Rang 6 aufzuwerten.\nErfordert Forschungsstufe 6 beim Archivarskodex und Ruhmstufe 75 oder höher.\n\"Durch den vollständigen Zugang zum Archivarskodex verstehen wir nun die bindende Macht der Herrschaftsmagie und deren Verhältnis zu den ersten Legierungen, die es in den Schattenlanden gab und die es uns ermöglichen, Eure Gegenstände aus Korthia und dem Schlund weiter zu verbessern.\"" }
entries[187139] = { ["name"] = "Abgefülltes Schemenherz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bricht das Siegel an der Flasche und erlaubt so dem darin enthaltenen Schemen, für kurze Zeit Besitz von Euch zu ergreifen. (1 Stunde Abklingzeit)\n\"Den Inhalt sollte man am besten ruhen lassen.\"" }
entries[187140] = { ["name"] = "Ring der Duplizität", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nutzt einen Teil der im Ring verbleibenden Magie, um ein Spiegelbild zu beschwören, das Eure Handlungen kopiert. (1 Stunde Abklingzeit)" }
entries[187141] = { ["name"] = "Makelloser Lupinkern", ["text"] = "Questgegenstand" }
entries[187142] = { ["name"] = "Makelloser Cervidenkern", ["text"] = "Questgegenstand" }
entries[187143] = { ["name"] = "Makelloser Raptorakern", ["text"] = "Questgegenstand" }
entries[187145] = { ["name"] = "Abhandlung: Erkennung und Nutzung von Stygia", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Gewährt Euch dauerhaft die Fähigkeit, 10 zusätzliche Stygia zu finden, wenn Ihr in Korthia oder im Schlund tägliche Quests abschließt, Schätze plündert oder seltene Kreaturen besiegt, die Stygia gewähren.\nErfordert Forschungsstufe 2 beim Archivarskodex." }
entries[187148] = { ["name"] = "Todesgebundener Splitter", ["text"] = "Wird beim Aufheben gebunden\nErfordert Forschungsstufe 6 beim Archivarskodex.\n\"Kann in der Schmiede der Bande benutzt werden, um ein unbekanntes Medium oder einen unbekannten Medienrang zu entdecken.\"" }
entries[187150] = { ["name"] = "Gorakklauenfetisch", ["text"] = "Korthianische Relikte\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Schrecklich anzuschauen und dazu noch äußerst übelriechend.\"" }
entries[187152] = { ["name"] = "Automaschlüssel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig" }
entries[187153] = { ["name"] = "Leckerer Schlundpilz", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bietet einen leckeren Schlundpilz an, um einen hungrigen Splitterfellbären anzulocken.\n\"Diese Pilze können nur einem richtig zähen Tier schmecken...\"" }
entries[187154] = { ["name"] = "Uralte korthianische Runen", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Werft die Runen, um das Schicksal zu enthüllen. (20 Sek. Abklingzeit)" }
entries[187155] = { ["name"] = "Tarnung des Wechselbalgs", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Nehmt das Aussehen eines Bediensteten von Korthia an. (30 Min Abklingzeit)\nVerkaufspreis:" }
entries[187158] = { ["name"] = "Entdunkelnder Oculus", ["text"] = "Questgegenstand\nEinzigartig\n\"Von Al'firim verzaubert, um Mittlerillusionen zu durchdringen.\"" }
entries[187159] = { ["name"] = "Schattenschnittkurzschwert", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Trennt den Schatten des anvisierten Spielercharakters ab. (5 Min Abklingzeit)" }
entries[187160] = { ["name"] = "Erinnerung an den bleichen Befehl", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBleicher Befehl Runenschnitzmacht\n[ Disziplin : Der Einsatz von 'Unheilige Nova' beschwört einen grüblerischen Kleriker. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des grüblerischen Klerikers um 2%, bis zu 100%.\n\nDer grüblerische Kleriker dient Euch 20 Sek. lang und heilt einen Verbündeten um (40% der Zaubermacht) Gesundheit. ] [ Schatten : Der Einsatz von 'Unheilige Nova' beschwört einen klappernden Magier. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des klappernden Magiers um 2%, bis zu 100%.\n\nDer klappernde Magier dient Euch 20 Sek. lang und überzieht Euer Ziel mit (25.1% der Zaubermacht) Schattenschaden. /\n\nHeilig\nDer Einsatz von 'Unheilige Nova' beschwört einen grüblerischen Kleriker. Jedes Mal, wenn ein Verbündeter einem mit 'Unheilige Transfusion' belegten Gegner Schaden zufügt, erhöhen sich Schaden und Heilung des grüblerischen Klerikers um 2%, bis zu 100%.\n\nDer grüblerische Kleriker dient Euch 20 Sek. lang und heilt einen Verbündeten um (40% der Zaubermacht) Gesundheit. ]\nRunenschnitzen: Füße, Finger\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Priester" }
entries[187161] = { ["name"] = "Erinnerung an Bwonsamdis Pakt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBwonsamdis Pakt Runenschnitzmacht Sofort\nGeht einen Pakt mit dem Loa des Todes ein und ruft eine verwunschene Maske hervor, die auf einem Ziel verbleibt, bis 'Faewächter' endet.\n\nVerwunschene Maske: Kopiert den Effekt der aktuell auf dem Ziel aktiven Fee. Folgt Eurem 'Maske leiten'.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Priester" }
entries[187162] = { ["name"] = "Erinnerung an das Schattenwort: Manipulation", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchattenwort: Manipulation Runenschnitzmacht Sofort\n'Gedankenspiele' hält 3 Sek. länger an und kehrt zusätzlich 10% Schaden oder Heilung um. Wenn 'Gedankenspiele' keinen Schaden oder keine Heilung mehr umkehren kann, erhaltet Ihr pro verbleibender Sekunde der Dauer 5% kritischen Trefferwert, der 10 Sek. lang anhält.\nRunenschnitzen: Hals, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Priester" }
entries[187163] = { ["name"] = "Erinnerung an die Harmonie der Sphären", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nHarmonie der Sphären Runenschnitzmacht Sofort\nDie Abklingzeit von 'Segen der Aufgestiegenen' wird pro Stapel von 'Segen der Aufgestiegenen', der von 'Aufgestiegene Eruption' verbraucht wird, um 3 Sek. verringert, bis zu maximal 60 Sek.\nRunenschnitzen: Schulter, Beine\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Priester" }
entries[187171] = { ["name"] = "Biomelone", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft ein Stück Obst. (1 Min Abklingzeit)\n\"Universalzerkleinerer\"" }
entries[187173] = { ["name"] = "Zuckendes Tentakel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft ein zuckendes Tentakel. (1 Min Abklingzeit)\n\"Universalzerkleinerer\"" }
entries[187174] = { ["name"] = "Verdunkelter Urteilsstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Richtet die Seele des anvisierten Gruppenmitglieds. Kann nur bei kürzlich Verstorbenen verwendet werden. (15 Min Abklingzeit)" }
entries[187175] = { ["name"] = "Barren des Runenwächters", ["text"] = "Anima\nWird beim Aufheben gebunden\nBenutzen: Lagert 250 gespeicherte Anima im Animareservoir Eures Pakts ein.\nVerkaufspreis:" }
entries[187176] = { ["name"] = "Vesperglocke der Harmonie", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert eine Vesperglocke der Harmonie vor Euch. (30 Min Abklingzeit)" }
entries[187177] = { ["name"] = "Korthianische Relikte erforschen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses Buch enthält genauere Informationen zu Relikten aus Korthia und der Forschung dazu.\"\nVerkaufspreis:" }
entries[187178] = { ["name"] = "Sc'ooties Lieblingsplüschtier", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft ein niedliches Plüschtier. (1 Min Abklingzeit)\n\"Universalzerkleinerer\"" }
entries[187179] = { ["name"] = "Leuchtstäbe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Wirft einen Leuchtstab. (1 Min Abklingzeit)\n\"Universalzerkleinerer\"" }
entries[187180] = { ["name"] = "Angefressener lichtdurchlässiger Flügel", ["text"] = "Verkaufspreis:" }
entries[187181] = { ["name"] = "Kleines Leichenfliegenei", ["text"] = "Wird beim Aufheben gebunden\nDauer: 3 tagen (Realzeit)\n\"Der Nachwuchs des Herrn der Halde dürfte es weit bringen.\"" }
entries[187182] = { ["name"] = "Schlüpfbereites Leichenfliegenei", ["text"] = "Wird beim Aufheben gebunden\n\"Schaut, was dem Ei entschlüpft.\"\n<Zum Öffnen rechtsklicken>" }
entries[187183] = { ["name"] = "Tobender Zerfleischer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Man würde eigentlich davon ausgehen, dass es schwierig ist, ein tobendes Reittier zu kontrollieren... Aber wenn es Euch gelingt, die Wildheit in eine bestimmte Richtung zu lenken, kann sie sogar ziemlich nützlich werden.\"\nBeute von:\nKonthrogz der Zerstörer\nZone:\nKorthia" }
entries[187184] = { ["name"] = "Vesperglocke der Klarheit", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert eine Vesperglocke der Klarheit vor Euch. (30 Min Abklingzeit)" }
entries[187185] = { ["name"] = "Vesperglocke des Glaubens", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Platziert eine Vesperglocke des Glaubens vor Euch. (30 Min Abklingzeit)" }
entries[187186] = { ["name"] = "Täuschungskugel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Kopiert das Erscheinungsbild eines Gegners, um ihn und seine Verbündeten hereinzulegen. Während Ihr verkleidet seid, verursacht Euer nächster Angriff 500% mehr Schaden.\n\"Verdächtig...\"" }
entries[187187] = { ["name"] = "Korthianische Ausrüstung", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Erschafft einen seelengebundenen korthianischen Gegenstand, der für Eure Beutespezialisierung nützlich ist.\nErfordert einen freundlichen Ruf beim Vorstoß des Todes." }
entries[187188] = { ["name"] = "D'roos bodenloser Schlucker", ["text"] = "\"So sehr Ihr Euch auch abmüht, es will Euch einfach nicht gelingen, ihn zu füllen.\"\nVerkaufspreis:" }
entries[187189] = { ["name"] = "Hyperlichtmultifunktionswerkzeug", ["text"] = "\"Erfunden von Di'lks vom Kartell Xy. Dieses unentbehrliche Werkzeug kommt überall zum Einsatz, wo Mittlertechnologie hergestellt wird.\"\nVerkaufspreis:" }
entries[187190] = { ["name"] = "Knopfhemd mit Blumendruck", ["text"] = "\"Ein klassisches und doch stilvolles Kleidungsstück, entworfen von N'uth vom Kartell Al.\"\nVerkaufspreis:" }
entries[187191] = { ["name"] = "Vi'llers bewahrtes Auge", ["text"] = "\"Es scheint Euch den Weg zu weisen, falls Ihr einmal vom Pfad abkommen solltet.\"\nVerkaufspreis:" }
entries[187192] = { ["name"] = "Urne des Wissens", ["text"] = "\"Die bewahrten Erinnerungen von Ny'lad vom Kartell Ta. Sie wurden sorgfältig redigiert und in die Urne gelegt, um weitere Studien vor dem Übergang in die nächste Daseinsebene zu ermöglichen.\"\nVerkaufspreis:" }
entries[187193] = { ["name"] = "Signierte Plüschmöwe", ["text"] = "\"Ein Paradebeispiel für atemberaubende Handwerkskunst. Auf den Schnabel wurde der Name \"K'en\" aufgestickt.\"\nVerkaufspreis:" }
entries[187194] = { ["name"] = "Stern im Glas", ["text"] = "\"Der Stern wurde von Sternzähmer Ja'z vom Kartell Zo vom Himmel gepflückt und dann sorgfältig in einem Glas platziert, damit auch andere ihn bewundern können.\"\nVerkaufspreis:" }
entries[187195] = { ["name"] = "Goldenes Saxophon", ["text"] = "\"Ein Instrument, das einst von Ta'ylor gespielt wurde, einem legendären Künstler, der in Myzas Oase aufgetreten ist.\"\nVerkaufspreis:" }
entries[187196] = { ["name"] = "Marke des endlosen Spielens", ["text"] = "\"Ta'piper hat einen unsichtbaren Faden an dieser Marke befestigt, was ihm und seinen Freunden endlose Stunden voller Spaß beschert.\"\nVerkaufspreis:" }
entries[187197] = { ["name"] = "D'roos Spukschlagzeug", ["text"] = "\"Dieses Schlagzeug scheint von einem charismatischen Geist heimgesucht zu werden, der immer dann zum Leben erwacht, wenn jemand in der Nähe einen Witz erzählt.\"\nVerkaufspreis:" }
entries[187198] = { ["name"] = "Xy'le-Dattel", ["text"] = "\"Dieser gängige Imbiss des Kartells Xy lässt sich ganz unkompliziert mit anderen genießen.\"\nVerkaufspreis:" }
entries[187199] = { ["name"] = "Pa'hix' Runenrätsel", ["text"] = "\"Ein kompliziertes Spiel, das man am besten mit Freunden löst. Wurde von der berühmten Codeknackerin höchstpersönlich erschaffen.\"\nVerkaufspreis:" }
entries[187200] = { ["name"] = "Singstahlbarren", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Entrüstet, beleidigt und auch sonst davon irritiert, dass die schlundgebundenen Stahlformer auf ihn einprügeln.\"" }
entries[187201] = { ["name"] = "Himmelskarte der Schattenlande", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Über der Schriftrolle schwebt eine wirbelnde multidimensionale Darstellung der relativen Positionen verschiedener jenseitiger Leben der Schattenlande.\"" }
entries[187202] = { ["name"] = "Instabile Sprengstoffkugel", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Dieses leuchtende und summende Gerät hat eindeutig noch das Potenzial, katastrophale Zerstörung zu verursachen.\"" }
entries[187203] = { ["name"] = "Chiffre der Erkenntnis", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Mehrere Textabschnitte wurden in verschiedenen Sprachen in den Stein geätzt. Jedoch handelt es sich bei keiner der Sprachen um eine Euch bekannte.\"" }
entries[187204] = { ["name"] = "Trommel des Todesloas", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Das Trommelfell, das über den Rahmen gespannt ist, fühlt sich ungewöhnlich kühl an.\"" }
entries[187205] = { ["name"] = "Sack voller fremdartiger Erde", ["text"] = "Korthianische Relikte\nQuestgegenstand\nDieser Gegenstand startet eine Quest.\n\"Die Erde in diesem Beutel ist von einem tiefen, kräftigen Braun... beinahe schon Schwarz.\"" }
entries[187206] = { ["name"] = "Buch der Bindung: Die wahnsinnige Hexe", ["text"] = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses Buch ist unvollständig. Eine verwirrte Stimme erklingt aus seinem Inneren und bittet wiederholt und nachdrücklich um die Wiederbeschaffung der blutroten Seiten.\"" }
entries[187207] = { ["name"] = "Geheimnisvolles Entschlüsselungsgerät", ["text"] = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ähnelt in seiner Konstruktion der Äthertechnologie der Mittler, ist aber unendlich komplexer.\"" }
entries[187208] = { ["name"] = "Schattenschnittkurzschwert", ["text"] = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Scharf und hell genug, um selbst Schatten zu durchtrennen.\"" }
entries[187209] = { ["name"] = "Holzschnitzerei der Familie Lang", ["text"] = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein verschlissenes Holzobjekt mit tiefen Furchen. Es muss tausende Jahre alt sein.\"" }
entries[187210] = { ["name"] = "Buch der Bindung: Der gepeinigte Zauberer", ["text"] = "Korthianische Relikte\nQuestgegenstand\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Dieses Buch ist unvollständig. Eine verwirrte Stimme erklingt aus seinem Inneren und bittet wiederholt und nachdrücklich um die Wiederbeschaffung der azurblauen Seiten.\"" }
entries[187211] = { ["name"] = "Chronik des Kartells Al", ["text"] = "\"Eine Sammlung niedergeschriebener Geschichten der größten Helden, die im Lauf der Zeitalter weitergegeben wurden. Von Al'len signiert.\"\nVerkaufspreis:" }
entries[187212] = { ["name"] = "Hyperlichtmokassins", ["text"] = "\"Mit diesen Mokassins hat By'ron, der größte Schuhmacher in Tazavesh, die perfekte Mischung aus Form und Funktion erschaffen.\"\nVerkaufspreis:" }
entries[187213] = { ["name"] = "Jos intergalaktische Truhe", ["text"] = "\"Das leuchtende Behältnis im Reiseformat enthält alles, was man braucht, um in jeder Ecke der Galaxie erfolgreich zu sein.\"\nVerkaufspreis:" }
entries[187216] = { ["name"] = "Seelenwindungssichel", ["text"] = "Wird beim Aufheben gebunden\n\"Kann in der Schmiede der Bande benutzt werden, um ein unbekanntes Medium oder einen unbekannten Medienrang zu entdecken.\"\nVerkaufspreis:" }
entries[187217] = { ["name"] = "Erinnerung an das großzügige Gebräu", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nGroßzügiges Gebräu Runenschnitzmacht Sofort\nCa. 1.5 Procs pro Minute\nEure Fähigkeiten haben eine geringe Chance, 'Knochenstaubgebräu' an der Position Eures Ziels einzusetzen. (500ms Abklingzeit)\nRunenschnitzen: Hals, Schulter, Brust\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Mönch" }
entries[187218] = { ["name"] = "Foliant der Ursprünge", ["text"] = "Wird beim Aufheben gebunden\nErfordert einen wohlwollenden Ruf beim Vorstoß des Todes." }
entries[187219] = { ["name"] = "Bedienstetenzeichen der Belobigung", ["text"] = "Saison 3 von Shadowlands\nWird beim Aufheben gebunden\nEinzigartig (12)\nVerkaufspreis:" }
entries[187220] = { ["name"] = "Gebündelte Macht", ["text"] = "Wird beim Aufheben gebunden\nBeim Aufsammeln: Gewährt den Animabonus 'Berechnender Angriff'.\n\"Eine seltsame Kugel, die Mittlermagie ausstrahlt.\"" }
entries[187221] = { ["name"] = "Seelenaschevorrat", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 250 Einheiten Seelenasche.\"\n<Zum Öffnen rechtsklicken>" }
entries[187222] = { ["name"] = "Stygiasingularität", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 500 Stygia.\"\n<Zum Öffnen rechtsklicken>" }
entries[187223] = { ["name"] = "Erinnerung an den Samen des ungezügelten Wachsens", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSamen des ungezügelten Wachsens Runenschnitzmacht Sofort\nJeder Impuls des Schadenseffekts von 'Faetransfusion' verringert die Abklingzeit von 'Wildgeist' um 9.0 Sek. und erhöht Eure kritische Trefferchance für 15 Sek. um 4%.\nRunenschnitzen: Kopf, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Schurke" }
entries[187224] = { ["name"] = "Erinnerung an die Elementarverbundenheit", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nElementarverbunden Runenschnitzmacht Sofort\nAuf bis zu 5 verbündete Ziele, die mit 'Kettenernte' geheilt wurden, wird 'Springflut' gewirkt. Auf bis zu 5 gegnerische Ziele, denen mit 'Kettenernte' Schaden zugefügt wurde, wird 'Flammenschock' gewirkt. Kritische Treffer mit 'Flammenschock' verringern die Abklingzeit von 'Kettenernte' um 1.0 Sek.\nRunenschnitzen: Brust, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt." }
entries[187225] = { ["name"] = "Erinnerung an den darbenden Seelendetritus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDarbender Seelendetritus Runenschnitzmacht Sofort\nWenn 'Geißelnder Obolus' Seelensplitter erzeugt, wird 8 Sek. lang Eure Bewegungsgeschwindigkeit um 100% und Eure kritische Trefferchance um 45% erhöht. Wenn 'Geißelnder Obolus' abläuft, wird stattdessen Eure Bewegungsgeschwindigkeit um 33% und Eure kritische Trefferchance um 15% erhöht.\nRunenschnitzen: Brust, Handgelenk, Rücken\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister" }
entries[187226] = { ["name"] = "Erinnerung an die Splitter der Vernichtung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSplitter der Vernichtung Runenschnitzmacht Sofort\n'Dezimierungsblitz' erhöht zusätzlich die kritische Trefferchance um 100% sowie den kritischen Schaden von [ Zerstörung : 'Verbrennen' / Seelendieb : 'Seelendieb' ] [ Dämonologie : 'Dämonenblitz' /\n\nGebrechen\n'Schattenblitz' ] um 50%.\nRunenschnitzen: Taille, Beine\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister" }
entries[187227] = { ["name"] = "Erinnerung an das verrottende Seelensäckchen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerrottendes Seelensäckchen Runenschnitzmacht Sofort\nJedes von 'Seelenfäule' betroffene Ziel erhöht Euer Tempo und Eure kritische Trefferchance 8 Sek. lang um 5%.\nRunenschnitzen: Füße, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister" }
entries[187228] = { ["name"] = "Erinnerung an die eingedämmte endlose Explosion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nEingedämmte endlose Explosion Runenschnitzmacht Sofort\nDer regelmäßige Schaden von 'Drohende Katastrophe' erhöht sich um 125% sowie zusätzlich um 15% pro auf dem Weg zum letzten Ziel getroffenem gegnerischen Ziel, bis zu maximal 275%.\nRunenschnitzen: Kopf, Hals, Schulter\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Hexenmeister" }
entries[187229] = { ["name"] = "Erinnerung an den Pakt der Seelenpirscher", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nPakt der Seelenpirscher Runenschnitzmacht Sofort\nWenn Euer 'Resonierender Pfeil' einem Ziel Schaden zufügt, wird die kritische Trefferchance Eurer Gruppe für 10 Sek. um 10% erhöht. (1s Abklingzeit)\nRunenschnitzen: Taille, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger" }
entries[187230] = { ["name"] = "Erinnerung an die Tasche mit Munition", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTasche mit Munition Runenschnitzmacht Sofort\nBis zu 2 der von Eurem 'Todeschakram' getroffenen Ziele werden zusätzlich von 'Explosivschuss' getroffen.\nRunenschnitzen: Kopf, Handgelenk\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger" }
entries[187231] = { ["name"] = "Erinnerung an die Fragmente des Ältestengeweihs", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFragmente des Ältestengeweihs Runenschnitzmacht Sofort\nWenn 'Wilde Geister' weniger als 5 Ziele trifft, besteht eine Chance von 100%, dass der Schaden von 'Wilde Geister' erneut verursacht wird.\nRunenschnitzen: Hals, Brust\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger" }
entries[187232] = { ["name"] = "Erinnerung an den Beutel mit Klingenbruchstücken", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nBeutel mit Klingenbruchstücken Runenschnitzmacht\nDurch 'Schinderschuss' ausgelöste Bonuseinsätze von 'Tödlicher Schuss' lassen 6 Ziele innerhalb von 12 Metern bluten, was ihnen 60% des von 'Tödlicher Schuss' verursachten Schadens im Verlauf von 6 Sek. zufügt.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Jäger" }
entries[187234] = { ["name"] = "Gebündelte Macht", ["text"] = "Wird beim Aufheben gebunden\nBeim Aufsammeln: Gewährt den Animabonus 'Refraktiver Schild'.\n\"Eine seltsame Kugel, die Mittlermagie ausstrahlt.\"" }
entries[187236] = { ["name"] = "Zovaals dunkle Karaffe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Trinkt. (30 Sek. Abklingzeit)\n\"Werdet Ihr daraus trinken oder wird sie Euch trinken?\"\nVerkaufspreis:" }
entries[187237] = { ["name"] = "Erinnerung an den Ruf zu den Waffen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRuf zu den Waffen Runenschnitzmacht Sofort\n'Waffen der Ordnung' ruft für 12 Sek. [ Braumeister : Niuzao, den Schwarzen Ochsen ] [ Nebelwirker : Chi-Ji, den Roten Kranich ] [ Windläufer : Xuen, den Weißen Tiger / Yu'lon, die Jadeschlange, ] zur Unterstützung an Eure Seite. (500ms Abklingzeit)\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Mönch" }
entries[187238] = { ["name"] = "Schwerer Stachelbalg", ["text"] = "Questgegenstand\n\"Ein zähes Stück Tierhaut, das mit brutalen Stacheln bedeckt ist.\"" }
entries[187239] = { ["name"] = "Verknöcherter ausgewachsener Schnabel", ["text"] = "Questgegenstand\n\"Dieser knochige, scharfe Schnabel kann durch jede Rüstung brechen.\"" }
entries[187240] = { ["name"] = "Wachsames Auge des Feldwächters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187241] = { ["name"] = "Wachsames Auge der Verdammten", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187242] = { ["name"] = "Verdammtenwappen des Exterminators", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187243] = { ["name"] = "Sichel des Schemenjägers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nRücken\n1 Rüstung\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187244] = { ["name"] = "Fragwürdige Schlundpilze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Essen auf eigene Gefahr! (30 Sek. Abklingzeit)\n\"Zu diesen seltsamen Gewächsen gibt es einige Fragen, die gestellt werden sollten.\"\nVerkaufspreis:" }
entries[187245] = { ["name"] = "Todesumwobene Spitzen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187246] = { ["name"] = "Todesumwobene Schulterstücke", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187247] = { ["name"] = "Todesumwobene Schulterstacheln", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187248] = { ["name"] = "Krokes glänzende Schiftung", ["text"] = "Kosmetisch\nWird beim Anlegen gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[187250] = { ["name"] = "Krokes Stachelschwingenschulterstücke", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinzigartig\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
