entries[187254] = { ["name"] = "Animaformation", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 175 Anima.\"\n<Zum Öffnen rechtsklicken>" }
entries[187255] = { ["name"] = "Hände des Widerstands: Chronik des Kummers", ["text"] = "Wird beim Aufheben gebunden\n\"Erzählt von einem Klan boshafter Riesen, die in den Schlund verbannt wurden und viele Strafen erleiden mussten, weil sie sich dem Kerkermeister widersetzt haben.\"\n<Zum Lesen rechtsklicken>" }
entries[187256] = { ["name"] = "Kuhls Ersatzfedora", ["text"] = "Gluthof\nWird beim Aufheben gebunden\nEinzigartig\n\"Schenkt dies Eurem Gräberbutler, damit er die Möglichkeit erhält, einen tollen Fedora zu tragen.\"\nVerkaufspreis:" }
entries[187258] = { ["name"] = "Erinnerung an die Faelinienharmonie", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFaelinienharmonie Runenschnitzmacht Sofort\nEure Fähigkeiten schließen die Abklingzeit von 'Faelinienstampfen' 100% häufiger ab. Durch 'Faelinienstampfen' getroffene Gegner und Verbündete werden mit 'Faekontakt' belegt, was Euren Schaden oder Eure Heilung bei ihnen 10 Sek. lang um 8% erhöht.\nRunenschnitzen: Taille, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Mönch" }
entries[187259] = { ["name"] = "Erinnerung an den tobenden Vortex der Vesperglocke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nTobender Vortex der Vesperglocke Runenschnitzmacht Sofort\nWenn 3 Aufladungen des Vespertotems verbraucht sind, strahlt das Vespertotem (300% der Zaubermacht) Arkanschaden und (110% der Zaubermacht) Heilung innerhalb von 15 Metern aus.\nRunenschnitzen: Beine, Füße\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt." }
entries[187264] = { ["name"] = "Ve'rayns Kopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Was für Geheimnisse könnte er noch enthalten?\"" }
entries[187274] = { ["name"] = "Uralte Legierung", ["text"] = "Questgegenstand\n\"Dieser Metallklumpen hat sich durch eine unfassbar alte Magie verfärbt.\"" }
entries[187275] = { ["name"] = "Schlachtpläne der Helgebundenen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Spionageberichte und Schlachtpläne für den Angriff auf die Zuflucht des Hüters.\"" }
entries[187276] = { ["name"] = "Gestohlene korthianische Vorräte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Von eindringenden Rissmonstern aus der Zuflucht des Hüters gestohlene Vorräte.\"" }
entries[187277] = { ["name"] = "Erinnerung an finstere Lehren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nFinstere Lehren Runenschnitzmacht Sofort\n'Gefallener Orden' beschwört für 24 Sek. 1 zusätzlichen [Ochsen][Kranich][Tiger]adepten. Während Euer mystisches Portal geöffnet ist, verringern kritische Treffer mit Euren Fähigkeiten die Abklingzeit von 'Gefallener Orden' um [ Nebelwirker : 2.5 /\n\nBraumeister, Windläufer\n5 ] Sek. (750ms Abklingzeit)\nRunenschnitzen: Handgelenk, Finger\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Mönch" }
entries[187278] = { ["name"] = "Krallendurchbohrte Schließkassette der Schlundgebundenen", ["text"] = "Wird beim Aufheben gebunden\n\"Bei Eurer Landung fiel sie aus der Kralle des Wildlings und ein paar Gegenstände purzelten heraus, doch es klappern noch mehr darin.\"\n<Zum Öffnen rechtsklicken>" }
entries[187280] = { ["name"] = "Erinnerung an das Herz der Fae", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nHerz der Fae Runenschnitzmacht Sofort\n'Machtverschiebung' kann aus der Bewegung kanalisiert werden. Ihr erhaltet für jeden von 'Machtverschiebung' getroffenen Gegner 1% kritischen Trefferwert und Tempo, bis zu 10%. Hält 15 Sek. lang an.\nRunenschnitzen: Brust, Hände\nQuelle: Wird auf Ruhmstufe 48 bei Eurem Pakt gewährt.\nBenötigt: Magier" }
entries[187281] = { ["name"] = "Wildlingsattel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Bei Eurem letzten Ritt hat ein entkommener Wildling ihn von sich heruntergleiten lassen und darauf bestanden, dass Ihr ihn behaltet.\"" }
entries[187282] = { ["name"] = "Intakter Aquilonkern", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Der Kern wurde von dem Verschlinger nicht beschädigt und könnte Euren eigenen Aquilon antreiben.\"" }
entries[187283] = { ["name"] = "Grabschwingenkristall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Er pulsiert vor Energie, und die Steinhauerin könnte ihn zur Schöpfung eines Reittiers verwenden.\"" }
