entries[187288] = { ["name"] = "Ominöser Splitter von Kyr", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Kyr (1)\nGewährt im Schlund alle 5 Sek. ( 123322 * (1 + Vielseitigkeit)) Absorption, bis zu maximal 616608 .\nVerkaufspreis:" }
entries[187289] = { ["name"] = "Ominöser Splitter von Tel", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Frostsplitter von Tel (1)\nIm Schlund lassen Eure kritischen Treffer einen Verbündeten in der Nähe die nächsten ( 31839 * (1 + Vielseitigkeit)) Schaden absorbieren, die er innerhalb von 6 Sek. erleidet.\nVerkaufspreis:" }
entries[187290] = { ["name"] = "Ominöser Splitter von Dyz", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Dyz (1)\nWenn Ihr im Schlund einem Ziel Schaden zufügt, wird Euer diesem Ziel zugefügter Schaden 4 Sek. lang um ( 1249 / 100)% erhöht. Bis zu 3-mal stapelbar.\nVerkaufspreis:" }
entries[187291] = { ["name"] = "Ominöser Splitter von Oth", ["text"] = "Splitter der Herrschaft\nWird beim Aufheben gebunden\nEinzigartig anlegbar: Unheiliger Splitter von Oth (1)\nIm Schlund ist Eure Geschwindigkeit ist um 1491 erhöht.\nVerkaufspreis:" }
